package com.hms.notifications;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="notification_messages") public class NotificationMessage { @Id private UUID id; @Column(nullable=false) private UUID tenantId; private UUID patientId; private UUID appointmentId; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationChannel channel; @Column(nullable=false,length=100) private String templateKey; @Column(nullable=false,length=180) private String recipient; @Column(length=180) private String subject; @Column(nullable=false,length=4000) private String body; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationStatus status; @Column(nullable=false) private boolean consentRequired; private OffsetDateTime sentAt; @Column(length=500) private String failureReason; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected NotificationMessage(){} public NotificationMessage(UUID tenantId,CreateNotificationRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;this.patientId=r.patientId();this.appointmentId=r.appointmentId();this.channel=r.channel();this.templateKey=r.templateKey();this.recipient=r.recipient();this.subject=r.subject();this.body=r.body();this.status=NotificationStatus.QUEUED;this.consentRequired=r.consentRequired();this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public NotificationStatus getStatus(){return status;} public NotificationChannel getChannel(){return channel;} public String getTemplateKey(){return templateKey;} public String getRecipient(){return recipient;} public String getBody(){return body;} public void markSent(){status=NotificationStatus.SENT;sentAt=OffsetDateTime.now();updatedAt=sentAt;} public void markFailed(String reason){status=NotificationStatus.FAILED;failureReason=reason;updatedAt=OffsetDateTime.now();} }
